   <script>
     const form = document.getElementById('support-form');
     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         requiredMessage: 'Please enter your full name.'
       },
       emailAddress: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         requiredMessage: 'Please enter your email address.',
         formatMessage: 'Please enter a valid email address.'
       },
       phoneNumber: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         formatMessage: 'Please use a phone number in the format (555) 123-4567 or 555-123-4567.'
       }
     };
     const status = document.getElementById('form-status');

     const phonePattern = /^(?:\+?1[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}$/;

     function setError(field, message) {
       field.error.textContent = message;
       field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
     }

     function validateName() {
       const value = fields.fullName.input.value.trim();
       if (!value) {
         setError(fields.fullName, fields.fullName.requiredMessage);
         return false;
       }
       setError(fields.fullName, '');
       return true;
     }

     function validateEmail() {
       const value = fields.emailAddress.input.value.trim();
       if (!value) {
         setError(fields.emailAddress, fields.emailAddress.requiredMessage);
         return false;
       }
       if (!fields.emailAddress.input.checkValidity()) {
         setError(fields.emailAddress, fields.emailAddress.formatMessage);
         return false;
       }
       setError(fields.emailAddress, '');
       return true;
     }

     function validatePhone() {
       const value = fields.phoneNumber.input.value.trim();
       if (!value) {
         setError(fields.phoneNumber, '');
         return true;
       }
       if (!phonePattern.test(value)) {
         setError(fields.phoneNumber, fields.phoneNumber.formatMessage);
         return false;
       }
       setError(fields.phoneNumber, '');
       return true;
     }

     function clearStatus() {
       status.textContent = '';
       status.removeAttribute('data-state');
     }

     Object.values(fields).forEach(({ input }) => {
       input.addEventListener('input', () => {
         clearStatus();
         if (input === fields.fullName.input) {
           validateName();
         } else if (input === fields.emailAddress.input) {
           validateEmail();
         } else {
           validatePhone();
         }
       });
       input.addEventListener('blur', () => {
         if (input === fields.fullName.input) {
           validateName();
         } else if (input === fields.emailAddress.input) {
           validateEmail();
         } else {
           validatePhone();
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       clearStatus();

       const validName = validateName();
       const validEmail = validateEmail();
       const validPhone = validatePhone();

       if (!validName || !validEmail || !validPhone) {
         const firstInvalid = [fields.fullName, fields.emailAddress, fields.phoneNumber]
           .find(({ input }) => input.getAttribute('aria-invalid') === 'true');
         if (firstInvalid) {
           firstInvalid.input.focus();
         }
         return;
       }

       form.reset();
       Object.values(fields).forEach(({ input, error }) => {
         input.removeAttribute('aria-invalid');
         error.textContent = '';
       });
       status.textContent = 'Thanks — your message is ready to send.';
       status.dataset.state = 'success';
     });
   </script>
 </body>
